/* Spectral Atlas: geometry is sourced; projections and curves are illustrations. */
(function(){'use strict';
const M=globalThis.AtlasModel,E=globalThis.IntegralEngine,$=id=>document.getElementById(id);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TAU=2*Math.PI,chapters=['phase','raghava','e8','mellin'];
const initial=location.hash.slice(1),state={chapter:chapters.includes(initial)?initial:'e8',selected:0,depth:.72,yaw:.45,pitch:.38,branch:0,power:1,primitive:false,j:1,denominator:6,kind:'E8',rank:7,target:4,weight:2,view:'balance',neighbors:true,playing:false};
let data,identity,frame=0,lastStep=0,drag=null,moved=false,screenPoints=[];
const C={ink:'#e5eee9',muted:'#97aeb8',cyan:'#7fdfd1',gold:'#e8bb75',violet:'#baa7e7',coral:'#ed9d8c',line:'#253a46',bg:'#08141e'};
const descriptions={
 e8:{number:'03 / THE ROOT SYSTEM',title:'E₈, made<br><em>tangible.</em>',description:'240 roots. Eight dimensions. One remarkable projection. Follow a root through its 30-step Coxeter orbit.',visual:'ACTUAL E8 ROOT COORDINATES',caption:'Select a root to inspect it. Drag to rotate; add depth to reveal a second Coxeter eigenspace.'},
 phase:{number:'01 / THE CYCLOTOMIC LIFT',title:'One phase.<br><em>264 lifts.</em>',description:'Lift a phase to a finer circle. Separate the 240 primitive branches from the 24 with lower conductor.',visual:'THE 1680 → 443520 REFINEMENT',caption:'Every point comes from an integer exponent. The power map acts on those actual phases.'},
 raghava:{number:'02 / THE ARCSINE CONNECTION',title:'An angle.<br><em>An exact sum.</em>',description:'Raghava’s arcsine identity collects an infinite series into a single power of an angle. See how its positive terms decay.',visual:'THE SHAPE OF CONVERGENCE',caption:'Each point is a positive summand divided by the exact sum. Its logarithmic height shows orders of magnitude.'},
 mellin:{number:'04 / THE MELLIN BALANCE',title:'Find the<br><em>vanishing point.</em>',description:'Root cycles add. Cartan directions subtract. Change the integral weight until their contributions balance exactly.',visual:'TWO CONTRIBUTIONS, ONE INTEGRAL',caption:'Above the line, the root contribution is larger. At the crossing, the complete normalized Mellin integral is zero.'}
};
const option=(v,label,current)=>`<option value="${v}"${String(v)===String(current)?' selected':''}>${label}</option>`;
const field=(id,label,value,input)=>`<div class="field"><div class="field-head"><label for="${id}">${label}</label>${value===null?'':`<output id="${id}-value" for="${id}">${value}</output>`}</div>${input}</div>`;
const range=(id,min,max,step,value)=>`<input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}">`;
const legend=items=>items.map(([label,color])=>`<span class="legend-item"><i class="legend-dot ${color||''}" aria-hidden="true"></i>${label}</span>`).join('');
const format=n=>n===0?'0':Math.abs(n)<.0001||Math.abs(n)>10000?n.toExponential(4):Number(n.toPrecision(6)).toLocaleString();
function proof(){
 if(state.chapter==='e8')return '<p>These are the actual 112 + 128 E8 roots, not arbitrary points on eight rings. Each root has squared length 2. Lines from a selected root join the 56 roots whose inner product with it is 1.</p><p>The flat view is the exponent-1 Coxeter plane. Depth adds the real exponent-7 projection; rotation changes the viewing angle. The coordinates are numerical projections of exact integer root data.</p><p>The root-space lift has been checked independently with 2,511,496 Jacobi triples and 245,024 bracket-preservation checks. This does not identify the roots with the primitive cyclotomic branches.</p>';
 if(state.chapter==='phase')return '<p>Let q = exp(iπ/840) and Q = exp(iπ/221760). Then Q²⁶⁴ = q. Its 264 lifts have exponents u = 1 + 1680j. Exactly 240 are coprime to 443520; the remaining 24 have conductor 40320.</p><p>384 is φ(1680), the base cyclotomic field degree. It is not the branch count. Each integer power shown here is an actual map z ↦ zᵖ; coincident images retain their input multiplicities.</p><p>The primitive polylogarithm sum reduces to 264<sup>1−s</sup>Li<sub>s</sub>(q) − 24<sup>1−s</sup>Li<sub>s</sub>(q⁶¹¹), for Re(s) &gt; 1. The real weight-two value is 22537π²/6773760.</p>';
 if(state.chapter==='raghava')return '<p>Set t = 2 sin θ. The series is ∑ e<sub>j−1</sub>(n)t<sup>2n</sup>/[n² C(2n,n)]. Here e<sub>r</sub>(n) is the coefficient of zʳ in ∏<sub>a&lt;n</sub>(1 + z/a²).</p><p>Its exact value is 4ʲθ<sup>2j</sup>/(2j)!, on the principal real arcsine branch |θ| &lt; π/2. The plotted heights are floating-point illustrations; the selected π coefficient is computed with integer fractions.</p><p><a href="https://arxiv.org/html/2607.09904v2" target="_blank" rel="noreferrer">Raghava’s paper and classical antecedents ↗</a> · <a href="./calculator.html">All 130 generating and 120 cancellation identities ↗</a></p>';
 return '<p>Z<sub>R</sub>(s) = Γ(s)<sup>−1</sup> ∫₀¹ (−log x)<sup>s−1</sup>K<sub>R</sub>(x) dx. We display Z<sub>R</sub>(s)/ζ(s); ζ(s) is positive for real s &gt; 1, so the zeros are unchanged.</p><p>For E8, the zero is s = 2. For Bₙ and Cₙ, it is s = 1 + log₂(n + 1). Choosing n = 2<sup>k−1</sup> − 1 prescribes any integer weight k ≥ 2. Their entire Mellin families agree although their root data differ.</p><p>At n = 7, K(x) = 7(15x¹³ − x⁶)/(1 − x¹⁴). The raw weight-four integral is zero, while its logarithmic companion is −π⁴ log 2 / 5145.</p><p>The balance graph uses log₂(root term / |Cartan term|). The density graph substitutes t = −log x, including the Jacobian e<sup>−t</sup>. Curves are numerical illustrations; selected integer coefficients are exact fractions.</p>';
}
function controls(){
